const BUSY_FLAG = Symbol("stdio_process_busy");

interface ManagedChildProcess extends ChildProcess {
	[BUSY_FLAG]?: boolean;
}

const activeProcesses = new Map<string, ManagedChildProcess>();

/** Default time to wait for the engine to answer before force-terminating it. */
const DEFAULT_TIMEOUT_MS = 5 * 60 * 1000;

/** Allowed commands for air-gapped defense-in-depth. */
const ALLOWED_COMMANDS = new Set(["python3", "python", "python3.11", "python3.12"]);

/**
 * Environment for the engine subprocess. The parent process may hold cloud API
 * keys; an air-gapped local engine has no use for them, so only pass through
 * what it needs to run.
 */
function buildChildEnv(): NodeJS.ProcessEnv {
	const passthroughPrefixes = ["OPENCODE_", "KAGGLE_", "MLX_", "HF_", "PYTHON"];
	const env: NodeJS.ProcessEnv = {};

	for (const name of ["PATH", "HOME", "TMPDIR", "LANG", "LC_ALL"]) {
		const value = process.env[name];
		if (value !== undefined) env[name] = value;
	}
	for (const [name, value] of Object.entries(process.env)) {
		if (value !== undefined && passthroughPrefixes.some((prefix) => name.startsWith(prefix))) {
			env[name] = value;
		}
	}

	return env;
}

function isAllowedCommand(cmd: string): boolean {
	const base = path.basename(cmd);
	return ALLOWED_C

OMMANDS.has(base) || cmd.startsWith(path.sep);
}

/** Remove all stream-specific listeners without touching management listeners. */
function sanitizeChildStreams(child: ManagedChildProcess) {
	if (child.stdout) {
		child.stdout.removeAllListeners("data");
	}
	if (child.stderr) {
		child.stderr.removeAllListeners("data");
	}
	// Remove previous stream()'s error/close listeners.
	// We intentionally leave exit listeners (registered by getOrSpawnChild) alone.
	child.removeAllListeners("error");
	child.removeAllListeners("close");
}

function getOrSpawnChild(command: string, args: string[]): ManagedChildProcess {
	const key = `${command} ${args.join(" ")}`;
	let child = activeProcesses.get(key);

	if (child && !child.killed && child.exitCode === null && child.stdin && !child.stdin.destroyed) {
		if (child[BUSY_FLAG]) {
			// Previous stream still marked busy — kill and respawn
			try {
				child.kill();
			} catch {
				// Ignore kill errors for stale process
			}
			activeProcesses.delete(key);
			child = undefined;
		} else {
			// FIX: Sanitize any stale listeners before reuse
			sanitizeChildStreams(child);
			return child;
		}
	}

	const newChild = spawn(command, args, {
		stdio: ["pipe", "pipe", "pipe"],
		env: buildChildEnv(),
	}) as ManagedChildProcess;
	newChild[BUSY_FLAG] = false;

	newChild.on("exit", () => {
		if (activeProcesses.get(key) === newChild) {
			activeProcesses.delete(key);
		}
		newChild[BUSY_FLAG] = false;
	});

	newChild.on("error", () => {
		if (activ

eProcesses.get(key) === newChild) {
			activeProcesses.delete(key);
		}
		newChild[BUSY_FLAG] = false;
	});

	activeProcesses.set(key, newChild);
	return newChild;
}

function buildMessages(context: Context): OpenAIChatMessage[] {
	const messages: OpenAIChatMessage[] = [];

	if (context.systemPrompt) {
		messages.push({ role: "system", content: context.systemPrompt });
	}

	for (const m of context.messages) {
		if (m.role === "user") {
			const contentStr =
				typeof m.content === "string"
					? m.content
					: m.content.map((c) => (c.type === "text" ? c.text : "[image]")).join("\n");
			messages.push({ role: "user", content: contentStr });
		} else if (m.role === "assistant") {
			const textParts: string[] = [];
			const toolCalls: OpenAIChatMessage["tool_calls"] = [];

			for (const c of m.content) {
				if (c.type === "text") {
					textParts.push(c.text);
				} else if (c.type === "thinking") {
					textParts.push(`${c.thinking}`);
				} else if (c.type === "toolCall") {
					toolCalls.push({
						id: c.id,
						type: "function",
						function: {
							name: c.name,
							arguments: JSON.stringify(c.arguments),
						},
					});
				}
			}

			messages.push({
				role: "assistant",
				content: textParts.join(""),
				...(toolCalls.length > 0 ? { tool_calls: toolCalls } : {}),
			});
		} else if (m.role === "toolResult") {
			const contentStr = m.content.map((c) => (c.type === "text" ? c.text : "")).join("");
			messages.push({
				role: "tool",
				tool_call_id:

m.toolCallId,
				content: contentStr,
			});
		}
	}

	return messages;
}

function buildTools(context: Context): OpenAITool[] | undefined {
	if (!context.tools?.length) return undefined;
	return context.tools.map((t) => ({
		type: "function",
		function: {
			name: t.name,
			description: t.description,
			parameters: t.parameters as Record<string, unknown> | undefined,
		},
	}));
}

export function stream(
	model: Model<"stdio-openai"> | Model<any>,
	context: Context,
	options?: StdioOpenAIOptions,
): AssistantMessageEventStream {
	const es = createAssistantMessageEventStream();

	// FIX: Generate correlation ID for request/response matching
	const requestId = crypto.randomUUID();

	const messages = buildMessages(context);
	const tools = buildTools(context);
	const payload = {
		request_id: requestId,
		model: model.id,
		messages,
		...(tools && tools.length > 0 ? { tools } : {}),
		temperature: options?.temperature ?? 0.7,
		max_tokens: options?.maxTokens ?? model.maxTokens ?? 8192,
		stream: true,
	};

	const command = options?.command ?? (model.baseUrl && !model.baseUrl.startsWith("http") ? model.baseUrl : "python3");
	const defaultEngineScript = path.resolve(process.env.OPENCODE_ROOT ?? process.cwd(), "scripts/mlx_engine.py");
	const args = options?.args ?? (command === "python3" ? [defaultEngineScript] : []);

	const assistantMessage: AssistantMessage = {
		role: "assistant",
		content: [],
		api: model.api,
		provider: model.provider,
		model: model.id,
		usage: {

input: 0,
		output: 0,
		cacheRead: 0,
		cacheWrite: 0,
		totalTokens: 0,
		cost: { input: 0, output: 0, cacheRead: 0, cacheWrite: 0, total: 0 },
	},
	stopReason: "pending",
	timestamp: Date.now(),
};

es.push({ type: "start", partial: assistantMessage });

// FIX: Air-gap defense-in-depth — validate command against allowlist
if (!isAllowedCommand(command)) {
	assistantMessage.stopReason = "error";
	assistantMessage.errorMessage = `Command "${command}" is not in the allowed list for air-gapped execution.`;
	es.push({ type: "error", reason: "error", error: assistantMessage });
	es.end(assistantMessage);
	return es;
}

let child: ManagedChildProcess;
try {
	child = getOrSpawnChild(command, args);
} catch (err) {
	assistantMessage.stopReason = "error";
	assistantMessage.errorMessage = err instanceof Error ? err.message : String(err);
	es.push({ type: "error", reason: "error", error: assistantMessage });
	es.end(assistantMessage);
	return es;
}

child[BUSY_FLAG] = true;

let stdoutBuffer = "";
let stderrBuffer = "";
let textIndex = -1;
let isDone = false;

const timeoutMs = options?.timeoutMs ?? DEFAULT_TIMEOUT_MS;
let hangTimer: ReturnType<typeof setTimeout> | undefined;

// Measured from the last received event rather than from the request, so a
// long-but-healthy generation is not killed mid-stream.
const armHangTimeout = () => {
	if (isDone || timeoutMs <= 0) return;
	if (hangTimer !== undefined) clearTimeout(hangTimer);
	hangTimer =

 setTimeout(onHangTimeout, timeoutMs);
		hangTimer.unref?.();
	};

	const cleanupListeners = () => {
		child[BUSY_FLAG] = false;
		if (hangTimer !== undefined) {
			clearTimeout(hangTimer);
			hangTimer = undefined;
		}
		if (child.stdout) {
			child.stdout.removeListener("data", onStdoutData);
		}
		if (child.stderr) {
			child.stderr.removeListener("data", onStderrData);
		}
		child.removeListener("error", ProcessError);
		child.removeListener("close", ProcessClose);
	};

	const finishStream = (reason: Extract<StopReason, "stop" | "toolUse">) => {
		if (isDone) return;
		isDone = true;

		cleanupListeners();

		if (options?.signal) {
			options.signal.removeEventListener("abort", onAbort);
		}

		if (textIndex >= 0) {
			const content = assistantMessage.content[textIndex] as TextContent;
			es.push({ type: "text_end", contentIndex: textIndex, content: content.text, partial: assistantMessage });
			textIndex = -1;
		}

		const hasToolCalls = assistantMessage.content.some((c) => c.type === "toolCall");
		assistantMessage.stopReason = hasToolCalls ? "toolUse" : reason;

		es.push({
			type: "done",
			reason: assistantMessage.stopReason as Extract<StopReason, "stop" | "toolUse">,
			message: assistantMessage,
		});
		es.end(assistantMessage);
	};

	const onAbort = () => {
		if (isDone) return;
		isDone = true;
		cleanupListeners();

		child.kill();
		if (assistantMessage.stopReason === "pending") {
			assistantMessage.stopReason = "aborted";
			assistantMessage.errorMessage =

"Request aborted by user";
			es.push({ type: "error", reason: "aborted", error: assistantMessage });
			es.end(assistantMessage);
		}
	};

	function onHangTimeout() {
		if (isDone) return;
		isDone = true;
		cleanupListeners();

		if (options?.signal) {
			options.signal.removeEventListener("abort", onAbort);
		}

		try {
			child.kill("SIGKILL");
		} catch {
			// Process may already be gone
		}

		assistantMessage.stopReason = "error";
		assistantMessage.errorMessage = `Model process produced no output for ${timeoutMs}ms and was terminated.${stderrBuffer ? ` stderr: ${stderrBuffer.trim()}` : ""}`;
		es.push({ type: "error", reason: "error", error: assistantMessage });
		es.end(assistantMessage);
	}

	if (options?.signal) {
		if (options.signal.aborted) {
			onAbort();
			return es;
		}
		options.signal.addEventListener("abort", onAbort, { once: true });
		// FIX: Double-check after attaching to close the race window
		if (options.signal.aborted) {
			onAbort();
			return es;
		}
	}

	const onStdoutData = (chunk: Buffer | string) => {
		if (isDone) return;

		armHangTimeout();
		stdoutBuffer += chunk.toString("utf8");
		const lines = stdoutBuffer.split("\n");
		stdoutBuffer = lines.pop() ?? "";

		for (const rawLine of lines) {
			let line = rawLine.trim();
			if (!line) continue;
			if (line.startsWith("data: ")) {
				line = line.slice(6).trim();
			}
			if (line === "[DONE]") {
				finishStream("stop");
				return;
			}

			try {
				const event = JSON.parse(line) as NDJ

SONEvent;

				// FIX: Ignore stale output from previous requests
				if (event.request_id && event.request_id !== requestId) {
					continue;
				}

				if (event.type === "done") {
					// FIX: Consume token usage from Python engine
					if (event.usage) {
						assistantMessage.usage.input = event.usage.prompt_tokens ?? 0;
						assistantMessage.usage.output = event.usage.completion_tokens ?? 0;
						assistantMessage.usage.totalTokens = event.usage.total_tokens ?? 0;
					}
					finishStream("stop");
					return;
				}

				if (event.type === "error") {
					isDone = true;
					cleanupListeners();
					if (options?.signal) {
						options.signal.removeEventListener("abort", onAbort);
					}
					assistantMessage.stopReason = "error";
					assistantMessage.errorMessage = event.error ?? "Unknown model error";
					es.push({ type: "error", reason: "error", error: assistantMessage });
					es.end(assistantMessage);
					return;
				}

				if (event.type === "text" && event.text) {
					if (textIndex === -1) {
						textIndex = assistantMessage.content.length;
						assistantMessage.content.push({ type: "text", text: "" });
						es.push({ type: "text_start", contentIndex: textIndex, partial: assistantMessage });
					}
					(assistantMessage.content[textIndex] as TextContent).text += event.text;
					es.push({
						type: "text_delta",
						contentIndex: textIndex,
						delta: event.text,
						partial: assistantMessage,
					});
					continue;
				}

				if (event.type ===

 "tool_call" && event.name) {
					if (textIndex >= 0) {
						const textContent = assistantMessage.content[textIndex] as TextContent;
						es.push({
							type: "text_end",
							contentIndex: textIndex,
							content: textContent.text,
							partial: assistantMessage,
						});
						textIndex = -1;
					}

					let parsedArgs: Record<string, unknown> = {};
					if (typeof event.arguments === "string") {
						try {
							parsedArgs = JSON.parse(event.arguments) as Record<string, unknown>;
						} catch {
							parsedArgs = { raw: event.arguments };
						}
					} else if (typeof event.arguments === "object" && event.arguments !== null) {
						parsedArgs = event.arguments;
					}

					const toolCall: ToolCall = {
						type: "toolCall",
						id: event.id ?? `call_${assistantMessage.content.length}`,
						name: event.name,
						arguments: parsedArgs,
					};

					const tcIndex = assistantMessage.content.length;
					assistantMessage.content.push(toolCall);
					es.push({ type: "toolcall_start", contentIndex: tcIndex, partial: assistantMessage });
					es.push({ type: "toolcall_end", contentIndex: tcIndex, toolCall, partial: assistantMessage });
					continue;
				}

				// Fallback for OpenAI-compatible streaming format
				const choice = event.choices?.[0];
				if (choice?.delta?.content) {
					if (textIndex === -1) {
						textIndex = assistantMessage.content.length;
						assistantMessage.content.push({ type: "text", text: "" });
						es.push({ type: "text_

start", contentIndex: textIndex, partial: assistantMessage });
					}
					(assistantMessage.content[textIndex] as TextContent).text += choice.delta.content;
					es.push({
						type: "text_delta",
						contentIndex: textIndex,
						delta: choice.delta.content,
						partial: assistantMessage,
					});
				}

				if (choice?.finish_reason === "stop" || choice?.finish_reason === "tool_calls") {
					finishStream(choice.finish_reason === "tool_calls" ? "toolUse" : "stop");
					return;
				}
			} catch {
				// Ignore non-JSON diagnostics or log output
			}
		}
	};

	const onStderrData = (chunk: Buffer | string) => {
		stderrBuffer += chunk.toString("utf8");
	};

	const ProcessError = (err: Error) => {
		if (isDone) return;
		isDone = true;
		cleanupListeners();
		if (options?.signal) {
			options.signal.removeEventListener("abort", onAbort);
		}

		assistantMessage.stopReason = "error";
		assistantMessage.errorMessage = err.message;
		es.push({ type: "error", reason: "error", error: assistantMessage });
		es.end(assistantMessage);
	};

	const ProcessClose = (code: number | null) => {
		if (isDone) return;
		isDone = true;
		cleanupListeners();
		if (options?.signal) {
			options.signal.removeEventListener("abort", onAbort);
		}

		if (code !== 0 && assistantMessage.stopReason === "pending") {
			assistantMessage.stopReason = "error";
			assistantMessage.errorMessage = `Process exited with code ${code}.${stderrBuffer ? ` stderr: ${stderrBuffer.trim()}` : ""}`;
			es.push({ t

ype: "error", reason: "error", error: assistantMessage });
			es.end(assistantMessage);
		} else {
			finishStream("stop");
		}
	};

	if (child.stdout) child.stdout.on("data", onStdoutData);
	if (child.stderr) child.stderr.on("data", onStderrData);
	child.on("error", ProcessError);
	child.on("close", ProcessClose);

	// FIX: Guard stdin.write against EPIPE and other write errors
	if (child.stdin) {
		const payloadLine = `${JSON.stringify(payload)}\n`;
		armHangTimeout();
		const ok = child.stdin.write(payloadLine, (err) => {
			if (err && !isDone) {
				isDone = true;
				cleanupListeners();
				if (options?.signal) {
					options.signal.removeEventListener("abort", onAbort);
				}
				assistantMessage.stopReason = "error";
				assistantMessage.errorMessage = `Failed to write to model process: ${err.message}`;
				es.push({ type: "error", reason: "error", error: assistantMessage });
				es.end(assistantMessage);
			}
		});
		if (!ok) {
			// Backpressure — child.stdin is full. For NDJSON this is rare,
			// but we could add a drain handler if needed.
		}
	}

	return es;
}

export function streamSimple(
	model: Model<"stdio-openai"> | Model<any>,
	context: Context,
	options?: SimpleStreamOptions,
): AssistantMessageEventStream {
	return stream(model, context, options);
}

import type { AuthContext } from "./types.ts";

interface NodeFsModule {
	access(path: string): Promise<void>;
}

interface NodeOsModule {
	homedir(): string;
}

// Variable specifier so browser bundlers do not try to resolve node builtins.
const importNodeModule = (specifier: string): Promise<unknown> => import(specifier);

function getProcessEnv(): Record<string, string | undefined> | undefined {
	const proc = (globalThis as { process?: { env?: Record<string, string | undefined> } }).process;
	return proc?.env;
}

/**
 * Default auth context: env vars from `process.env` (undefined in browsers),
 * file existence via node:fs (always false in browsers).
 */
export function defaultProviderAuthContext(): AuthContext {
	return {
		async env(name: string): Promise<string | undefined> {
			const value = getProcessEnv()?.[name];
			return typeof value === "string" && value.trim().length > 0 ? value : undefined;
		},

		async fileExists(path: string): Promise<boolean> {
			try {
				const fs = (await importNodeModule("node:fs/promises")) as NodeFsModule;
				let resolved = path;
				if (resolved.startsWith("~")) {
					const os = (await importNodeModule("node:os")) as NodeOsModule;
					resolved = os.homedir() + resolved.slice(1);
				}
				await fs.access(resolved);
				return true;
			} catch {
				return false;
			}
		},
	};
}

import type { Credential, CredentialInfo, CredentialStore } from "./types.ts";

/**
 * Default in-memory credential store. Apps inject persistent stores.
 * Keyed by `Provider.id`, one credential per provider; see `CredentialStore`.
 * Writes are serialized per provider through a promise chain.
 */
export class InMemoryCredentialStore implements CredentialStore {
	private credentials = new Map<string, Credential>();
	private chains = new Map<string, Promise<unknown>>();

	/** Serialize tasks per provider id. */
	private enqueue<T>(providerId: string, task: () => Promise<T>): Promise<T> {
		const previous = this.chains.get(providerId) ?? Promise.resolve();
		const next = (async () => {
			await previous.catch(() => {});
			return task();
		})();
		this.chains.set(
			providerId,
			next.catch(() => {}),
		);
		return next;
	}

	async read(providerId: string): Promise<Credential | undefined> {
		return this.credentials.get(providerId);
	}

	async list(): Promise<readonly CredentialInfo[]> {
		return [...this.credentials].map(([providerId, credential]) => ({ providerId, type: credential.type }));
	}

	modify(
		providerId: string,
		fn: (current: Credential | undefined) => Promise<Credential | undefined>,
	): Promise<Credential | undefined> {
		return this.enqueue(providerId, async () => {
			const current = this.credentials.get(providerId);
			const next = await fn(current);
			if (next !== undefined) this.credentials.set(providerId, next);
			return next ?? current;
		});
	}

	delete(providerId: string): Promise<void> {
		return this.enqueue(providerId, async () => {
			this.credentials.delete(providerId);
		});
	}
}

import type { ApiKeyAuth, OAuthAuth } from "./types.ts";

/**
 * Standard api-key auth: a stored credential key wins, otherwise the first
 * set env var resolves. Includes a `login` that prompts for the key.
 * Providers with non-standard resolution (provider env, ambient files, IAM)
 * write their own `ApiKeyAuth`.
 */
export function envApiKeyAuth(name: string, envVars: readonly string[]): ApiKeyAuth {
	return {
		name,
		login: async (interaction) => {
			const key = await interaction.prompt({ type: "secret", message: `Enter ${name}` });
			return { type: "api_key", key };
		},
		resolve: async ({ ctx, credential }) => {
			if (credential?.key) {
				return { auth: { apiKey: credential.key }, env: credential.env, source: "stored credential" };
			}
			for (const envVar of envVars) {
				const value = await ctx.env(envVar);
				if (value) return { auth: { apiKey: value }, source: envVar };
			}
			return undefined;
		},
	};
}

/**
 * Wraps a dynamically imported `OAuthAuth` so provider definitions can
 * advertise OAuth without importing the implementation. The flow loads on
 * first `login`/`refresh`/`toAuth` call; callers keep Node-only flow code out
 * of bundles by loading through a bundler-opaque dynamic import (variable
 * specifier, see the bedrock lazy wrapper).
 */
export function lazyOAuth(input: { name: string; loginLabel?: string; load: () => Promise<OAuthAuth> }): OAuthAuth {
	let promise: Promise<OAuthAuth> | undefined;
	const loaded = () => {
		promise ??= in

put.load();
		return promise;
	};
	return {
		name: input.name,
		loginLabel: input.loginLabel,
		login: async (interaction) => (await loaded()).login(interaction),
		refresh: async (credential) => (await loaded()).refresh(credential),
		toAuth: async (credential) => (await loaded()).toAuth(credential),
	};
}

import type { ProviderEnv } from "../types.ts";
import { formatThrownValue } from "../utils/diagnostics.ts";
import type {
	ApiKeyAuth,
	ApiKeyCredential,
	AuthContext,
	AuthResult,
	Credential,
	CredentialStore,
	OAuthAuth,
	OAuthCredential,
	ProviderAuth,
} from "./types.ts";

export type ModelsErrorCode = "model_source" | "model_validation" | "provider" | "stream" | "auth" | "oauth";

export interface AuthResolutionOverrides {
	apiKey?: string;
	env?: ProviderEnv;
	/** Require this much remaining OAuth-token validity; defaults to five minutes. */
	minOAuthValidityMs?: number;
}

export class ModelsError extends Error {
	readonly code: ModelsErrorCode;

	constructor(code: ModelsErrorCode, message: string, options?: { cause?: unknown }) {
		super(withCauseDetail(message, options?.cause), options);
		this.name = "ModelsError";
		this.code = code;
	}
}

/** Callers surface `error.message` only, so keep the underlying reason in it. */
function withCauseDetail(message: string, cause: unknown): string {
	if (cause === undefined || cause === null) return message;
	const detail = formatThrownValue(cause).trim();
	if (!detail || message.includes(detail)) return message;
	return `${message}: ${detail}`;
}

/**
 * Auth resolution shared by the `Models` and `ImagesModels` collections.
 * A stored credential owns the provider: ambient/env is consulted only when
 * nothing is stored. No silent env fallback after a failed refresh or for a
 * credential type without a matching handler.
 */

export async function resolveProviderAuth(
	provider: { id: string; auth: ProviderAuth },
	credentials: CredentialStore,
	authContext: AuthContext,
	overrides?: AuthResolutionOverrides,
): Promise<AuthResult | undefined> {
	const requestAuthContext = overrides?.env ? overlayEnvAuthContext(authContext, overrides.env) : authContext;

	if (overrides?.apiKey !== undefined && provider.auth.apiKey) {
		return resolveApiKey(requestAuthContext, provider.auth.apiKey, provider.id, {
			type: "api_key",
			key: overrides.apiKey,
			env: overrides.env,
		});
	}

	const stored = await readCredential(credentials, provider.id);
	if (stored) {
		if (stored.type === "oauth" && provider.auth.oauth) {
			return resolveStoredOAuth(
				credentials,
				provider.id,
				provider.auth.oauth,
				stored,
				overrides?.minOAuthValidityMs,
			);
		}
		if (stored.type === "api_key" && provider.auth.apiKey) {
			const credential = overrides?.env ? { ...stored, env: { ...stored.env, ...overrides.env } } : stored;
			return resolveApiKey(requestAuthContext, provider.auth.apiKey, provider.id, credential);
		}
		return undefined;
	}

	// Ambient (env vars, AWS profiles, ADC files).
	return provider.auth.apiKey
		? resolveApiKey(requestAuthContext, provider.auth.apiKey, provider.id, undefined)
		: undefined;
}

function overlayEnvAuthContext(base: AuthContext, env: ProviderEnv): AuthContext {
	return {
		env: async (name) => env[name] || (await base.env(name)),
		fileExists: (path) => base.fileExists(path

),
	};
}

const DEFAULT_OAUTH_MINIMUM_VALIDITY_MS = 5 * 60 * 1000;

/**
 * OAuth resolution with double-checked locking: tokens with less than five
 * minutes remaining lock, re-check expiry under the lock, refresh once
 * globally, and persist the rotated credential before release.
 */
async function resolveStoredOAuth(
	credentials: CredentialStore,
	providerId: string,
	oauth: OAuthAuth,
	stored: OAuthCredential,
	minOAuthValidityMs?: number,
): Promise<AuthResult | undefined> {
	const minimumValidityMs = Math.max(DEFAULT_OAUTH_MINIMUM_VALIDITY_MS, minOAuthValidityMs ?? 0);
	const expiresSoon = (credential: OAuthCredential) => Date.now() + minimumValidityMs >= credential.expires;
	let credential = stored;

	if (expiresSoon(credential)) {
		// Optimistic check said expired; the authoritative check runs under the lock.
		let post: Credential | undefined;
		try {
			post = await credentials.modify(providerId, async (current) => {
				if (current?.type !== "oauth") return undefined; // logged out meanwhile
				if (!expiresSoon(current)) return undefined; // another process/request refreshed
				try {
					return await oauth.refresh(current);
				} catch (error) {
					throw new ModelsError("oauth", `OAuth refresh failed for ${providerId}`, { cause: error });
				}
			});
		} catch (error) {
			if (error instanceof ModelsError) throw error;
			throw new ModelsError("auth", `Credential store modify failed for ${providerId}`, { cause: error });
		}
		if (post?.type !== "oauth") r

eturn undefined; // logged out meanwhile
		credential = post;
		// The normal five-minute window triggers a refresh but does not impose a
		// provider contract. Explicit callers (such as bearer-token export) do
		// require the requested minimum after the refresh.
		if (minOAuthValidityMs !== undefined && expiresSoon(credential)) {
			throw new ModelsError("oauth", `OAuth refresh returned a token that expires too soon for ${providerId}`);
		}
	}

	try {
		return { auth: await oauth.toAuth(credential), source: "OAuth" };
	} catch (error) {
		throw new ModelsError("oauth", `OAuth auth derivation failed for ${providerId}`, { cause: error });
	}
}

async function resolveApiKey(
	authContext: AuthContext,
	apiKey: ApiKeyAuth,
	providerId: string,
	credential: ApiKeyCredential | undefined,
): Promise<AuthResult | undefined> {
	try {
		return await apiKey.resolve({ ctx: authContext, credential });
	} catch (error) {
		throw new ModelsError("auth", `API key auth failed for provider ${providerId}`, { cause: error });
	}
}

async function readCredential(credentials: CredentialStore, providerId: string): Promise<Credential | undefined> {
	try {
		return await credentials.read(providerId);
	} catch (error) {
		throw new ModelsError("auth", `Credential store read failed for ${providerId}`, { cause: error });
	}
}

import type { ProviderEnv, ProviderHeaders } from "../types.ts";

/**
 * Request auth for a single model request. If a value cannot be expressed as
 * `apiKey`, `headers`, or `baseUrl`, it is provider config, not auth.
 */
export interface ModelAuth {
	apiKey?: string;
	headers?: ProviderHeaders;
	baseUrl?: string;
}

/**
 * Stored api-key credential. `env` holds provider-scoped environment/config
 * values such as Cloudflare account/gateway ids.
 */
export interface ApiKeyCredential {
	type: "api_key";
	key?: string;
	env?: ProviderEnv;
}

/** OAuth token data returned by extension compatibility flows. */
export interface OAuthCredentials {
	refresh: string;
	access: string;
	expires: number;
	[key: string]: unknown;
}

/** Stored canonical OAuth credential. */
export interface OAuthCredential extends OAuthCredentials {
	type: "oauth";
}

/** One type-tagged credential per provider — the shape of today's auth.json. */
export type Credential = ApiKeyCredential | OAuthCredential;

/** Non-secret credential metadata for account/status enumeration. */
export interface CredentialInfo {
	providerId: string;
	type: Credential["type"];
}

/**
 * App-owned credential storage, keyed by `Provider.id`, one credential per
 * provider. `modify` is the only write path, so every mutation is a
 * serialized read-modify-write; `Models.getAuth()` runs OAuth refresh inside
 * `modify` so concurrent requests cannot double-refresh a rotated token. The
 * app persists a credential after login via

 * `modify(provider.id, async () => credential)`. Login/logout orchestration
 * is app-owned.
 *
 * Error semantics: `read` resolves `undefined` for missing entries. Methods
 * reject only on storage failure; `Models` wraps such rejections in
 * `ModelsError` with code "auth". Best-effort stores that serve an in-memory
 * view and record persistence errors internally (like coding-agent's
 * AuthStorage) are valid implementations.
 */
export interface CredentialStore {
	/**
	 * Read the stored credential, possibly expired. Display/status use;
	 * resolved request auth comes from `Models.getAuth()`.
	 */
	read(providerId: string): Promise<Credential | undefined>;

	/**
	 * List stored credential metadata without resolving or exposing secrets.
	 * Implementations must not execute configured API-key commands while listing.
	 */
	list(): Promise<readonly CredentialInfo[]>;

	/**
	 * Serialized write — the only write path. `fn` sees the current credential
	 * because correct writes (refresh, login-during-refresh) depend on it;
	 * return the new credential, or undefined to leave the entry unchanged.
	 * Mutual exclusion per provider id, cross-process too where the backing
	 * store supports it (e.g. a file lock). Resolves with the post-write
	 * credential. Rejections from `fn` propagate.
	 */
	modify(
		providerId: string,
		fn: (current: Credential | undefined) => Promise<Credential | undefined>,
	): Promise<Credential | undefined>;

	/** Remove a credential (logout). Implementat

ions serialize this against `modify`. */
	delete(providerId: string): Promise<void>;
}

/** Environment access for auth resolution. Injectable for tests and browsers. */
export interface AuthContext {
	env(name: string): Promise<string | undefined>;
	/** Check whether a file exists. Supports a leading `~`. Always false in browsers. */
	fileExists(path: string): Promise<boolean>;
}

/** Result of resolving auth for a model. */
export interface AuthResult {
	auth: ModelAuth;
	/** Provider-scoped environment/config values resolved from credentials and ambient context. */
	env?: ProviderEnv;
	/** Human-readable label for status UI: "ANTHROPIC_API_KEY", "OAuth", "~/.aws/credentials". */
	source?: string;
}

export interface AuthCheck {
	source?: string;
	type: "api_key" | "oauth";
}

export type AuthType = "api_key" | "oauth";

/**
 * Prompt shown to the user during login. `signal` lets the flow cancel a
 * pending prompt when an out-of-band event resolves the step, e.g. a
 * `manual_code` prompt raced against a callback server, aborted when the
 * callback wins.
 */
export type AuthPrompt = { signal?: AbortSignal } & (
	| { type: "text"; message: string; placeholder?: string }
	| { type: "secret"; message: string; placeholder?: string }
	| { type: "select"; message: string; options: readonly { id: string; label: string; description?: string }[] }
	| { type: "manual_code"; message: string; placeholder?: string }
);

export interface AuthInfoLink {
	url: string;
	label?: string;
}

export type AuthEvent =
	| { type: "info"; message: string; links?: readonly AuthInfoLink[] }
	| { type: "auth_url"; url: string; instructions?: string }
	| {
			type: "device_code";
			userCode: string;
			verificationUri: string;
			intervalSeconds?: number;
			expiresInSeconds?: number;
	  }
	| { type: "progress"; message: string };

/**
 * Login interaction callbacks serving both api-key and OAuth flows.
 *
 * `prompt()` returns the entered/selected string (`select` returns the option
 * id). Rejects on cancel/abort. `signal` aborts the whole login flow;
 * per-prompt cancellation uses `AuthPrompt.signal`.
 */
export interface AuthInteraction {
	signal?: AbortSignal;

	prompt(prompt: AuthPrompt): Promise<string>;
	notify(event: AuthEvent): void;
}

/**
 * Api-key auth: stored key/provider env plus ambient sources (env vars, AWS
 * profiles, ADC files). Ambient-only providers omit `login`.
 */
export interface ApiKeyAuth {
	/** Display name, e.g. "Anthropic API key". */
	name: string;

	/** Interactive setup (prompt for key/provider env). Absent = ambient-only. */
	login?(interaction: AuthInteraction): Promise<ApiKeyCredential>;

	/**
	 * Optional side-effect-free availability check. Use this when `resolve()` may
	 * execute commands or perform other request-time work. Missing means Models
	 * checks availability by resolving auth.
	 */
	check?(input: { ctx: AuthContext; credential?: ApiKeyCredential }): Promise<AuthCheck | undefined>;

	/**
	 * Resolve auth from the stor

ed credential and/or ambient sources, merging
	 * per field (`credential.key ?? env("...")`, `credential.env?.NAME ?? env("...")`).
	 * undefined = not configured. Resolution is provider-scoped; model-specific
	 * endpoint preparation happens after auth has been resolved.
	 */
	resolve(input: { ctx: AuthContext; credential?: ApiKeyCredential }): Promise<AuthResult | undefined>;
}

/**
 * OAuth auth. The `refresh`/`toAuth` split lets `Models` own the locked
 * refresh pattern: `refresh` produces a credential, `toAuth` derives request
 * auth from whatever credential ends up stored.
 */
export interface OAuthAuth {
	/** Display name, e.g. "Anthropic (Claude Pro/Max)". */
	name: string;

	/** Selector label for the subscription login option, e.g. "Sign in with SuperGrok or X Premium". */
	loginLabel?: string;

	login(interaction: AuthInteraction): Promise<OAuthCredential>;

	/**
	 * Exchange the refresh token. Network call; throws on failure
	 * (invalid_grant etc.). `Models` runs this under the store lock.
	 */
	refresh(credential: OAuthCredential, signal?: AbortSignal): Promise<OAuthCredential>;

	/**
	 * Side-effect-free derivation of request auth from a valid credential.
	 * Covers per-credential baseUrl (GitHub Copilot). Async so lazy wrappers
	 * can load the implementation on first use.
	 */
	toAuth(credential: OAuthCredential): Promise<ModelAuth>;
}

/**
 * Provider auth. At least one of `apiKey`/`oauth` must be present: even
 * ambient-credential providers and keyless l

ocal servers provide `apiKey`
 * auth whose `resolve()` reports whether the provider is configured.
 */
export interface ProviderAuth {
	apiKey?: ApiKeyAuth;
	oauth?: OAuthAuth;
}

