			: "";
	console.log(`${chalk.bold(APP_NAME)} - Local AI coding assistant (read, bash, edit, write tools)

${chalk.bold("Usage:")}
  ${APP_NAME} [option

.padEnd(32)} - Config directory (default: ~/${CONFIG_DIR_NAME}/agent)
  ${ENV_SESSION_DIR.padEnd(32)} - Session storage directory (overridden by --session-dir)
  PI_PACKAGE_DIR                   - Override package directory (for Nix/Guix store paths)
`);
