export interface SqliteStatement {
	run(...params: unknown[]): Promise<SqliteRunResult>;
	get<TRow extends object>(...params: unknown[]): Promise<TRow | undefined>;
	all<TRow extends object>(...params: unknown[]): Promise<TRow[]>;
}

